style.css:
@-moz-document domain("roblox.com") {
/* تعديل شكل الشات في روبلوكس */
    #chat-container {
        background: rgba(0, 0, 0, 0.6) !important; /* خلفية شفافة */
        border-radius: 10px !important; /* زوايا دائرية */
        padding: 10px !important;
    }

    /* تعديل الفقاعات داخل الشات */
    .chat-message {
        background: linear-gradient(45deg, #007bff, #00c3ff) !important; /* لون متدرج */
        color: white !important; /* لون الخط */
        font-weight: bold !important;
        border-radius: 15px !important; /* زوايا ناعمة */
        padding: 8px 12px !important;
        box-shadow: 0px 0px 10px rgba(0, 195, 255, 0.6) !important; /* وهج أزرق */
    }

    /* تعديل النصوص */
    .chat-message .chat-username {
        color: #ffcc00 !important; /* لون مميز للأسماء */
        font-weight: bold !important;
        text-shadow: 0px 0px 5px rgba(255, 204, 0, 0.7) !important;
    }

    /* تأثير عند تمرير الماوس */
    .chat-message:hover {
        transform: scale(1.05);
        transition: 0.3s ease-in-out;
    }

    /* تأثير الإرسال */
    @keyframes chat-pop {
        0% {
            transform: scale(0.8);
            opacity: 0;
        }
        100% {
            transform: scale(1);
            opacity: 1;
        }
    }

    .chat-message {
        animation: chat-pop 0.3s ease-in-out;
    }
}
